Nu,Ou=tonumber(Mu.eff3)*V.secRescale(Ku),tonumber(Mu.matches3)
else
Nu,Ou=(tonumber(Mu.eff)or 1)*V.effRescale(Ku)*V.secRescale(Ku),tonumber(Mu.matches)or 5
end
if not Lu and V.SUMMONER[Ku]then
Nu,Ou=Nu*(V.sumRescale(Ku)or 1)*(1-(V.SUMMONER[Ku].droneShare or 0)),math.min(Ou,10)
end
return Nu,Ou
end
function V.footK(Pu)
