if not(Qu and Su)then
return 1/Uu
end
return V.nudgeFrom(math.log(math.max(0.01,Qu))*Ru,Ru)/V.nudgeFrom(math.log(math.max(0.01,Su))*Tu,Tu)/Uu
end
