return nil
end
local Xw={weak={},strong={},res={}}
for Yw,Zw in pairs(type(Ww._weak_against)==ffe[1977]and Ww._weak_against or type(Ww.weak_against)==ffe[1977]and Ww.weak_against or{})do
local _w=type(Zw)==ffe[1977]and Zw.damage_type or(type(Zw)==ffe[884]and Zw)or nil
if _w then
Xw.weak[_w]=type(Zw)==ffe[1977]and W.weakAmp(Zw.amplification)or 1.5
end
end
for ax,bx in pairs(type(Ww._strong_against)==ffe[1977]and Ww._strong_against or type(Ww.strong_against)==ffe[1977]and Ww.strong_against or{})do
local cx=type(bx)==ffe[1977]and bx.damage_type or(type(bx)==ffe[884]and bx)or nil
local dx,ex=type(bx)==ffe[1977]and tonumber(bx.amplification),type(bx)==ffe[1977]and tonumber(bx.resistance)
if cx then
if ex then
Xw.res[cx]=100/(100+ex)
elseif dx and dx<1 then
Xw.res[cx]=dx
else
Xw.strong[cx]=true
end
end
end
return(next(Xw.weak)or next(Xw.strong)or next(Xw.res))and Xw or nil
end
