W._levelMod={}
function W.levelMod(jx)
if jx==nil then
return nil
end
if W._levelMod[jx]~=nil then
return W._levelMod[jx]or nil
end
W._levelMod[jx]=false
local kx=N.Levels[jx]
local lx=type(kx)==ffe[1977]and N.Waves[kx.waves or jx]
local mx=type(lx)==ffe[1977]and lx.initial_unit_configs
if type(mx)~=ffe[1977]then
return nil
end
local nx,ox,px={},{},0
for qx,rx in pairs(mx)do
local sx=type(rx)==ffe[1977]and type(rx.override_stats)==ffe[1977]and(rx.override_stats[1]or rx.override_stats[ffe[2418]])or nil
if type(sx)==ffe[1977]then
local tx=tonumber(sx.health)or 20
px=px+tx
table.insert(nx,{hp=tx,st=sx})
for ux in pairs(sx)do
local vx=tostring(ux):match(ffe[2123])or tostring(ux):match(ffe[2419])
if vx then
ox[vx]=true
end
end
end
end
if not next(ox)or px<=0 then
return nil
end
local wx={weak={},strong={},res={}}
for xx in pairs(ox)do
local yx=0
for zx,Ax in ipairs(nx)do
local Bx=(1+(tonumber(Ax.st[ffe[2260]..xx])or 0))*100/(100+math.max(0,tonumber(Ax.st[ffe[2420]..xx])or 0))
yx=yx+Ax.hp/math.max(0.05,Bx)
end
local Cx=px/math.max(1,yx)
if Cx>1.02 then
wx.weak[xx]=Cx
elseif Cx<0.98 then
wx.res[xx]=Cx
end
end
if not(next(wx.weak)or next(wx.res))then
return nil
end
W._levelMod[jx]=wx
return wx
end
function W.dailyMod(Dx,Ex,Fx)
