Hx.weak[Jx]=Gx and 1+Gx:NextNumber(0.5,0.7)or 1.5
end
for Kx,Lx in pairs(Fx or{})do
if Gx then
Hx.res[Lx]=100/(100+Gx:NextNumber(100,150))
else
Hx.strong[Lx]=true
end
end
return Hx
end
