return cG(ffe[2577],IG,KG)
end
F.log(1,ffe[2481],string.format(ffe[2578],GG-AG(),(tonumber(((N.prof().capsule_pity_data or{})[mb.STAR]or{}).total_opens)or 0)))
ab.pickNote.skins=nil
