function ib.plan(Xeb,Yeb,Zeb)
local _eb=N.session()
local afb=table.clone(Zeb)
table.sort(afb)
local bfb=table.concat(afb,ffe[2828])
local cfb=(tonumber((P.simCal[Xeb.key]or{}).n)or 0)>0
