local efb=bfb..ffe[2291]..Yeb.uuid..(cfb and ffe[3143]or ffe[3144])..ffe[3145]
local ffb=P.trainSim[Xeb.key]
if ffb and ffb.sig==efb and not ffb.pending and os.time()-(ffb.at or 0)<6*3600 then
return ffb
end
local gfb={sig=efb,base=bfb,uuid=Yeb.uuid,at=os.time(),ok=false,margin=dfb,pending=true}
P.trainSim[Xeb.key]=gfb
local hfb,ifb=gb.levelFor(Xeb)
if Xeb.ldOverride then
hfb=Xeb.ldOverride
end
if not hfb then
gfb.why,gfb.pending=ffe[3146],nil
return gfb
end
local jfb=gb.info(hfb,Xeb.key,ifb,Xeb.mod)
local kfb={}
for lfb,mfb in ipairs(Zeb)do
local nfb=_eb.collection:get_unit_by_uuid(mfb)
if nfb then
table.insert(kfb,nfb)
end
end
local ofb=_eb.collection:get_unit_by_uuid(Yeb.uuid)
if not ofb or#kfb==0 then
gfb.why,gfb.pending=ffe[3147],nil
return gfb
end
local pfb=gb.run(jfb,gb.teamFrom(kfb,jfb.map),{hpMul=1})
local qfb=jfb.infinite and gb.unbound(hfb)
local rfb=qfb and W.infTier(gb.run(jfb,gb.teamFrom(kfb,jfb.map),{hpMul=dfb}).wave)or nil
local sfb={}
for tfb,ufb in ipairs(kfb)do
if not V.isFarm(ufb.unit_id)then
local vfb,wfb=pcall(V.score,ufb,Xeb.mod)
table.insert(sfb,{i=tfb,sc=vfb and wfb or 0})
end
end
table.sort(sfb,function(xfb,yfb)
return xfb.sc<yfb.sc
end)
local zfb
for Afb=1,math.min(3,#sfb)do
local Bfb=table.clone(kfb)
Bfb[sfb[Afb].i]=ofb
local Cfb=gb.teamFrom(Bfb,jfb.map)
local Dfb=gb.run(jfb,Cfb,{hpMul=dfb,train=Yeb.uuid})
if(qfb and W.infTier(Dfb.wave)>=rfb)or(not qfb and Dfb.won)then
local Efb=gb.run(jfb,Cfb,{hpMul=1,train=Yeb.uuid})
local Ffb=(Efb.tk or 0)/math.max(0.5,Efb.t/60)
if(Efb.won or qfb)and(not zfb or Ffb>math.max(zfb.rate*1.5,zfb.rate+1))then
zfb={out=kfb[sfb[Afb].i].unit_id,r=Efb,rate=Ffb,trial=Bfb}
end
end
end
gfb.ownMin=pfb.t/60
if not zfb then
gfb.why=qfb and string.format(ffe[3148],rfb,cfb and ffe[3149]or ffe[3150])or cfb and ffe[3151]or ffe[3152]
else
gfb.out,gfb.tk,gfb.minutes=zfb.out,zfb.r.tk or 0,zfb.r.t/60
gfb.uuids={}
for Gfb,Hfb in ipairs(zfb.trial)do
table.insert(gfb.uuids,Hfb.uuid)
end
gfb.slow=(pfb.won and not qfb)and gfb.minutes/math.max(0.1,gfb.ownMin)or 1
if gfb.tk<=0 and next(P.train.real)==nil then
gfb.why=ffe[3153]
elseif gfb.slow>ib.SLOW then
gfb.why=string.format(ffe[3154],math.floor((gfb.slow-1)*100+0.5))
else
gfb.ok=true
end
end
gfb.pending=nil
F.log(1,ffe[3155],string.format(ffe[3156],Xeb.label,V.name(Yeb.id),gfb.out and(ffe[3157]..V.name(gfb.out))or ffe[898],gfb.ok and string.format(ffe[3158],math.floor((ib.perRun(Xeb.key,Yeb.id)or 0)+0.5),Yeb.what,gfb.minutes,gfb.ownMin)or tostring(gfb.why)))
F.saveSoon()
return gfb
