if Bnb and not W.done(tnb,Bnb.id,ffe[903])then
unb,vnb,wnb=ynb,Anb[1],Bnb
break
end
end
end
if not(unb and snb[unb]and vnb and wnb)then
return
end
if W.open(wnb.id)or not W.open(vnb.id)then
return
end
P.worldSkip=type(P.worldSkip)==ffe[1977]and P.worldSkip or{}
local Cnb=P.worldSkip[unb]
if type(Cnb)==ffe[1977]and(Cnb.done or os.time()-(tonumber(Cnb.at)or 0)<ab.WORLD_SKIP_RETRY)then
return
end
local Dnb=N.Worlds[unb]
local Enb=tostring(Dnb and Dnb.name or unb)
local Fnb={key=ffe[2659]..wnb.id..ffe[2764],kind=ffe[2016],first=true,level=wnb.id,diff=ffe[903],label=W.levelName(wnb.id)..ffe[2765]}
local Gnb,Hnb=pcall(gb.plan,Fnb,false)
if not(Gnb and type(Hnb)==ffe[1977])then
return
end
if not Hnb.won then
if ab.every(ffe[3331]..unb,3600)then
F.log(1,ffe[2592],string.format(ffe[3332],Enb,W.levelName(wnb.id),tostring(Hnb.margin)))
end
return
end
local Inb={}
for Jnb,Knb in ipairs(U.list(Dnb.levels))do
Inb[Knb.id]=W.done(tnb,Knb.id,ffe[903])
end
local Lnb=U.now()
F.log(1,ffe[2592],string.format(ffe[3333],Enb,W.levelName(wnb.id),tostring(Hnb.margin)))
local Mnb,Nnb=F.request(ffe[3334],ffe[3335],unb)
