while U.now()-Lnb<8 do
task.wait(1)
if W.open(wnb.id)then
Onb=true
break
end
end
local Pnb=F.gameSaid(Lnb)
P.worldSkip[unb]={at=os.time(),done=Onb or nil,last=wnb.id,said=Pnb and tostring(Pnb):sub(1,80)or nil}
F.saveSoon()
if Onb then
local Qnb=(N.prof()or{}).level_data or{}
local Rnb={}
for Snb,Tnb in ipairs(U.list(Dnb.levels))do
if Tnb.id~=wnb.id and not Inb[Tnb.id]and W.done(Qnb,Tnb.id,ffe[903])then
table.insert(Rnb,W.levelName(Tnb.id))
end
end
F.log(1,ffe[2592],string.format(ffe[3336],Enb,#Rnb>0 and(ffe[3337]..table.concat(Rnb,ffe[2089]))or ffe[3338],Pnb and(ffe[3339]..tostring(Pnb))or ffe[898]))
W.lastScored=nil
else
F.log(1,ffe[2592],string.format(ffe[3340],Enb,tostring(Pnb or(Mnb and Nnb)or ffe[2563])))
end
end
