local Mxb=(Kxb.cd>0 and Kxb.damage/Kxb.cd or 0)*V.aoe(Kxb.atk,Kxb.range)/math.max(0.3,V.aoe(Jxb.atk,Jxb.range))
local Nxb=Lxb>0 and Dxb*(Mxb/Lxb-1)or(Ixb or 0)
local Oxb=Exb[Fxb+2]
if Oxb and Fxb+1<Exb.max and Oxb.cd>0 and Kxb.cd>0 and Lxb>0 then
local Pxb=Dxb*((Oxb.damage/Oxb.cd)/Lxb-1)
local Qxb=Gxb+Oxb.cost*Hxb
if Pxb/Qxb>Nxb/Gxb then
Nxb=Nxb+(Pxb/Qxb*Gxb-Nxb)*0.5
end
end
local Rxb=(Kxb.range or 0)>(Jxb.range or 0)and(1+((Kxb.range-Jxb.range)/math.max(1,Jxb.range)))or 1
return math.max(0,Nxb)*Rxb
end
function eb.dpsFor(Sxb,Txb)
if Txb<=0 then
return 0
