local Uxb={}
for Vxb,Wxb in ipairs(Sxb)do
if not Wxb.farm and Wxb.gain>0 then
table.insert(Uxb,Wxb)
end
end
table.sort(Uxb,function(Xxb,Yxb)
return Xxb.gain/Xxb.cost>Yxb.gain/Yxb.cost
end)
local Zxb,_xb=0,0
for ayb,byb in ipairs(Uxb)do
if Txb<=0 then
break
end
_xb=byb.gain/byb.cost
local cyb=math.min(1,Txb/byb.cost)
Zxb=Zxb+byb.gain*cyb
Txb=Txb-byb.cost*cyb
end
return Zxb+math.max(0,Txb)*_xb*0.7
end
function eb.shieldDps(dyb,eyb,fyb,gyb,hyb,iyb,jyb)
if(gyb or 0)<=0 or(dyb or 0)<=0 or(hyb or 0)<=0 then
return dyb or 0
end
eyb,fyb,iyb=math.max(0.3,eyb or 2),math.max(1,fyb or 1),iyb or 1
local kyb=dyb*iyb*eyb/fyb
return hyb*fyb/((gyb/math.max(1,jyb or 1)+math.max(1,hyb/kyb))*eyb)/iyb
end
function eb.shieldGain(lyb,myb,nyb,oyb,pyb,qyb,ryb,syb)
local tyb,uyb=V.attackInfo(myb.atk,myb.range),V.attackInfo(oyb.atk,oyb.range)
