local xyb=math.max(0,((tonumber(oyb.range)or 0)-(tonumber(myb.range)or 0))/math.max(1,tonumber(myb.range)or 1))
return math.max(0,wyb-vyb)+vyb*xyb
end
function eb.shieldWork(yyb,zyb,Ayb,Byb,Cyb,Dyb,Eyb,Fyb,Gyb)
