function jb.openChests(egc,fgc)
local ggc,hgc,igc=jb.res(egc)
local jgc=jb.lives(egc)
local kgc=jb.cleared(egc)
if not(fgc or kgc>=jb.ROOMS or jgc<=1)then
jb.note(string.format(ffe[3900],kgc,hgc,igc,jb.luck(egc)))
F.request(ffe[3886],ffe[3887])
return
end
local lgc,mgc,ngc=0,0,0
local ogc=tonumber(N.cur(ffe[2041]))or 0
local pgc=jb.wallet()
for qgc=1,hgc+igc+4 do
local rgc,sgc,tgc=jb.res(jb.data())
if sgc+tgc<=0 or ngc>=2 then
break
end
local ugc,vgc
if sgc>0 then
ugc,vgc=F.request(ffe[3901],ffe[3902])
else
ugc,vgc=F.request(ffe[3901],ffe[3902],true)
end
if ugc and vgc~=nil then
F.log(1,ffe[3870],ffe[3903]..(type(vgc)==ffe[1977]and U.json(U.plain(vgc)):sub(1,300)or tostring(vgc)))
end
local wgc=U.now()
while U.now()-wgc<4 do
local xgc,ygc,zgc=jb.res(jb.data())
if ygc<sgc or zgc<tgc then
break
end
task.wait(0.25)
end
local Agc,Bgc,Cgc=jb.res(jb.data())
if Bgc<sgc then
lgc=lgc+(sgc-Bgc)
ngc=0
elseif Cgc<tgc then
mgc=mgc+(tgc-Cgc)
ngc=0
else
ngc=ngc+1
end
task.wait(1)
if Bgc<sgc or Cgc<tgc then
local Dgc=jb.wallet()
local Egc=jb.walletDiff(pgc,Dgc)
F.log(1,ffe[3870],(Cgc<tgc and ffe[3904]or ffe[3903])..Egc)
P.dg.pay=P.dg.pay or{}
local Fgc={}
for Ggc,Hgc in pairs(Dgc.items)do
if Hgc~=(pgc.items[Ggc]or 0)then
Fgc[Ggc]=Hgc-(pgc.items[Ggc]or 0)
end
end
table.insert(P.dg.pay,{at=os.time(),rare=Cgc<tgc,gems=Dgc.gems-pgc.gems,luck=jb.luck(egc),paid=Egc,items=Fgc})
while#P.dg.pay>60 do
table.remove(P.dg.pay,1)
end
pgc=Dgc
end
end
jb.note(string.format(ffe[3905],lgc,mgc,fgc and ffe[3906]or(jgc<=1 and ffe[3907]or ffe[3908]),jb.luck(egc),(tonumber(N.cur(ffe[2041]))or 0)-ogc))
local Igc,Jgc,Kgc=jb.res(jb.data())
if(fgc or kgc>=jb.ROOMS)and Jgc+Kgc>0 then
jb.note(string.format(ffe[3909],Jgc,Kgc))
W.rec(ffe[2689]).restUntil=os.time()+1800
return ffe[3910]
end
if not fgc then
F.request(ffe[3886],ffe[3887])
end
end
function jb.act(Lgc)
local Mgc,Ngc=jb.state(Lgc)
jb.logState(Lgc,Mgc)
if Mgc==ffe[3869]then
return false
end
if Mgc==ffe[3868]then
jb.note(string.format(ffe[3911],tostring(Ngc and Ngc.t)))
F.request(ffe[3886],ffe[3887])
return true
end
if Mgc==ffe[2734]then
F.request(ffe[3912],ffe[3913])
jb.note(ffe[3914])
P.dg.lives,P.dg.lost,P.dg.bailed,P.dg.bails=5,{},{},{}
elseif Mgc==ffe[3866]then
if jb.openChests(Lgc,true)==ffe[3910]then
return ffe[3910]
end
F.request(ffe[3886],ffe[3887])
local Ogc,Pgc,Qgc=jb.res(jb.data())
table.insert(P.dg.runs,1,{at=os.time(),depth=jb.ROOMS,items=U.count(jb.items(Lgc)),left=Pgc+Qgc})
while#P.dg.runs>10 do
table.remove(P.dg.runs)
end
jb.note(ffe[3915])
elseif Mgc==ffe[3007]then
jb.shop(Lgc,Ngc)
elseif Mgc==ffe[3821]then
jb.shrine(Lgc,Ngc)
elseif Mgc==ffe[3867]then
if jb.openChests(Lgc,false)==ffe[3910]then
return ffe[3910]
end
end
return true
end
function jb.launch(Rgc)
local Sgc=jb.data()
if not Sgc then
F.backoff(ffe[3347],30)
return false
end
if not Sgc._started then
if not(O.dungeonStart or O.onlyDungeons)then
return false
end
local Tgc,Ugc=F.request(ffe[3916],ffe[3917])
task.wait(2.5)
Sgc=jb.data()
if not(Tgc and Sgc and Sgc._started)then
F.log(1,ffe[3870],ffe[3918]..tostring(Ugc)..ffe[3919])
W.rec(ffe[2689]).restUntil=os.time()+1800
F.backoff(ffe[3347],10)
return false
end
P.dg.lost,P.dg.bailed,P.dg.bails={},{},{}
jb.note(ffe[3920])
end
if jb.enter(Sgc,Rgc.value,false)then
return true
end
F.backoff(ffe[3347],10)
return false
end
function jb.playLast()
local Vgc=P.dg.playLast
return type(Vgc)==ffe[1977]and os.time()-(tonumber(Vgc.at)or 0)<1800 and Vgc or nil
end
function jb.forced(Wgc)
local Xgc=P.dg.force
if type(Xgc)~=ffe[1977]or type(Xgc.uuids)~=ffe[1977]or Xgc.seed~=tostring(Wgc.r._r)then
return nil
end
if os.time()-(tonumber(Xgc.at)or 0)>3600 then
P.dg.force=nil
return nil
end
return Xgc
end
function jb.startTeam(Ygc,Zgc,_gc,ahc)
P.startTeam={uuids=table.clone(Ygc),must=true,own=ahc or nil,seed=tostring(Zgc.r._r),why=_gc}
end
function jb.planTeam(bhc,chc,dhc)
