end
F.log(1,ffe[3616],string.format(ffe[3923],bhc.d,tostring(ehc.label)))
ab.equipTeam(ehc.uuids,tostring(ehc.label))
task.wait(0.5)
return
end
if dhc and not O.autoTeam then
return
end
local fhc=P.simTeam.dg
if not dhc and O.autoTeam and fhc and fhc.better and not fhc.stale and fhc.seed==tostring(bhc.r._r)and os.time()-(tonumber(fhc.at)or 0)<300 then
ab.equipTeam(fhc.uuids,ffe[3924]..bhc.d)
task.wait(0.5)
return
end
local ghc=jb.fx(chc,jb.roomCurse(bhc.r))
local hhc={}
