if lhc then
table.insert(hhc,lhc)
end
end
else
for mhc,nhc in ipairs(V.equipped())do
table.insert(hhc,nhc.u)
end
end
if#hhc==0 then
return
end
local ohc=jb.mod(bhc.r._l)
local phc=gb.applyFx(gb.info(gb.slim(bhc.r._l),ffe[2689],nil,ohc),ghc)
local qhc=jb.applyK(phc,bhc.r._r)
if qhc>1 then
F.log(1,ffe[3616],string.format(ffe[3925],bhc.d,qhc))
end
F.status(ffe[3008],ffe[3926]..bhc.d)
gb.memoOn()
local rhc=jb.ways(phc)
local shc=type(P.dg.styles)==ffe[1977]and P.dg.styles[tostring(bhc.r._r)]or nil
local function thc(uhc,vhc)
local whc=gb.sig(uhc)
local xhc=type(P.dg.teams)==ffe[1977]and P.dg.teams[whc]or{}
local yhc=type(P.dg.lost)==ffe[1977]and P.dg.lost[tostring(bhc.r._r)]and P.dg.lost[tostring(bhc.r._r)][whc]or 0
local zhc=type(P.dg.bailed)==ffe[1977]and type(P.dg.bailed[tostring(bhc.r._r)])==ffe[1977]and tonumber(P.dg.bailed[tostring(bhc.r._r)][whc])or 0
yhc=yhc+zhc
local Ahc,Bhc,Chc,Dhc=gb.strength(vhc.info,uhc)
local Ehc=math.clamp((tonumber(xhc.w)or 0)-2*(tonumber(xhc.l)or 0),-6,3)
if bhc.d>=13 then
Ehc=math.min(Ehc,1)
end
Ehc=Ehc-3*yhc
local Fhc=shc and type(shc.lost)==ffe[1977]and shc.lost[vhc.style]or nil
if type(Fhc)==ffe[1977]and Fhc.sig==whc then
Ehc=Ehc-3
end
return{score=Ahc+Ehc,wins=Ahc,atOne=Bhc,reach=Chc,far=Dhc,lostHere=yhc,left=zhc,w=tonumber(xhc.w)or 0,l=tonumber(xhc.l)or 0,style=vhc.style}
end
local function Ghc(Hhc)
for Ihc,Jhc in ipairs(rhc)do
if Jhc.style==Hhc then
return Jhc
end
end
return rhc[2]
end
local function Khc(Lhc,Mhc)
return not Mhc or Lhc.score>Mhc.score or(Lhc.score==Mhc.score and(Lhc.far or 0)>(Mhc.far or 0))
end
local function Nhc(Ohc)
local Phc
for Qhc,Rhc in ipairs(rhc)do
local Shc=thc(Ohc,Rhc)
if Khc(Shc,Phc)then
Phc=Shc
end
task.wait()
end
return Phc
end
local Thc=Nhc(hhc)
if Thc.wins>=3* #gb.LADDER and Thc.lostHere==0 then
gb.memo=nil
local Uhc,Vhc={},{}
for Whc,Xhc in ipairs(hhc)do
table.insert(Uhc,Xhc.uuid)
table.insert(Vhc,V.name(Xhc.unit_id))
end
P.simTeam.dg={uuids=Uhc,names=Vhc,won=true,wave=phc.total,better=false,cur={won=true,wave=phc.total},at=os.time(),label=ffe[3927],seed=tostring(bhc.r._r),style=Thc.style}
F.log(1,ffe[3616],string.format(ffe[3928],bhc.d,gb.LADDER[#gb.LADDER],Thc.w,Thc.l))
pcall(function()
local Yhc,Zhc=pcall(jb.roomName,bhc)
gb.explainSave(ffe[2689],string.format(ffe[3929],bhc.d,Yhc and tostring(Zhc)or ffe[2212]),phc,hhc,{string.format(ffe[3930],gb.LADDER[#gb.LADDER],Thc.w,Thc.l)},false,hhc,{won=true,wave=phc.total,total=phc.total,steps=Thc.wins,mySteps=Thc.wins,realW=Thc.w,realL=Thc.l})
end)
if dhc and type(P.savedTeam)==ffe[1977]and not ib.same(ib.team(),P.savedTeam)then
