local _hc=gb.pool(ohc,phc)
local aic=(jb.lives(chc)<=1 and 45 or 20)/ #rhc
local bic,cic,dic,eic
for fic,gic in ipairs(rhc)do
local hic,iic,jic,kic=gb.bestTeam(gic.info,hhc,_hc,aic)
local lic=thc(hic,gic)
if Khc(lic,eic)then
bic,cic,dic,eic=hic,iic,kic,lic
end
end
local mic=gb.sig(bic)==gb.sig(hhc)
if mic then
eic=Thc
end
if(phc.regen or 0)>0 then
local nic=false
for oic,pic in ipairs(hhc)do
if V.bleeds(pic.unit_id)then
nic=true
end
end
for qic,ric in ipairs(bic)do
if V.bleeds(ric.unit_id)then
nic=true
end
end
local sic=not nic and V.bestBleeder(hhc)or nil
if sic then
local tic={}
for uic,vic in ipairs(hhc)do
if not V.isFarm(vic.unit_id)and not V.allyBuff(vic.unit_id)then
local wic=table.clone(hhc)
wic[uic]=sic
local xic=thc(wic,Ghc(eic.style))
table.insert(tic,string.format(ffe[3932],V.name(vic.unit_id),xic.wins))
if xic.score>eic.score then
bic,eic,mic=wic,xic,false
cic={won=xic.wins>0,wave=xic.reach}
end
task.wait()
end
end
F.log(1,ffe[3616],string.format(ffe[3933],bhc.d,V.name(sic.unit_id),V.bleeds(sic.unit_id)or 0,table.concat(tic,ffe[2352])))
jb.bleedTried=string.format(ffe[3934],V.name(sic.unit_id),V.bleeds(sic.unit_id)or 0,table.concat(tic,ffe[2352]))
end
end
gb.memo=nil
local yic=eic.wins>Thc.wins or(eic.wins==Thc.wins and(eic.far or 0)>(Thc.far or 0))
local zic=not mic and yic and eic.lostHere<=Thc.lostHere
local Aic,Bic={},{}
for Cic,Dic in ipairs(bic)do
table.insert(Aic,Dic.uuid)
table.insert(Bic,V.name(Dic.unit_id))
end
P.simTeam.dg={uuids=Aic,names=Bic,won=cic.won,wave=cic.wave,better=zic,cur={won=dic.won,wave=dic.wave},at=os.time(),label=ffe[3927],seed=tostring(bhc.r._r),style=(zic and eic.style)or Thc.style}
local function Eic(Fic)
