end
pcall(function()
local Gic={string.format(ffe[3936],#_hc)}
if jb.bleedTried then
table.insert(Gic,jb.bleedTried)
end
jb.bleedTried=nil
local function Hic(Iic)
return string.format(ffe[3937],Iic.wins,3* #gb.LADDER,jb.WAY_WORDS[Iic.style]or ffe[898],Iic.w,Iic.l,(Iic.lostHere or 0)>0 and string.format(ffe[3938],Iic.lostHere,(Iic.left or 0)>0 and string.format(ffe[3939],Iic.left)or ffe[898])or ffe[898])
end
if mic and Thc.wins>=3* #gb.LADDER then
