elseif not yic then
table.insert(Gic,ffe[3945])
else
table.insert(Gic,string.format(ffe[3946],eic.lostHere))
end
end
local Jic,Kic=pcall(jb.roomName,bhc)
local Lic=zic and eic or Thc
gb.explainSave(ffe[2689],string.format(ffe[3929],bhc.d,Jic and tostring(Kic)or ffe[2212]),phc,zic and bic or hhc,Gic,zic,hhc,{won=zic and cic.won or dic.won,wave=zic and cic.wave or dic.wave,total=phc.total,steps=Lic.wins,mySteps=Thc.wins,realW=Lic.w,realL=Lic.l})
end)
if not zic then
if mic and Thc.wins>=3* #gb.LADDER then
