else
F.log(1,ffe[3616],string.format(ffe[3950],bhc.d,Eic(Thc),table.concat(Bic,ffe[2089]),eic.lostHere,Eic(eic)))
end
if dhc and type(P.savedTeam)==ffe[1977]and not ib.same(ib.team(),P.savedTeam)then
