function jb.enter(Mic,Nic,Oic)
for Pic=1,5 do
local Qic,Ric=pcall(jb.act,Mic)
if not Qic then
F.log(1,ffe[2363],ffe[3954]..tostring(Ric))
break
end
if Ric==ffe[3910]then
return false
end
if not Ric then
break
end
task.wait(2)
Mic=jb.data()
if not(Mic and Mic._started)then
return false
end
end
jb._pick=nil
local Sic=jb.pick(Mic)
if not Sic then
jb.logState(Mic,ffe[3955])
local Tic,Uic,Vic=jb.res(Mic)
if Uic+Vic>0 then
F.log(1,ffe[3870],string.format(ffe[3956],Uic,Vic))
W.rec(ffe[2689]).restUntil=os.time()+1800
return false
end
