F.request(ffe[3886],ffe[3887])
return false
end
local Wic,Xic=pcall(jb.planTeam,Sic,Mic,Oic)
if not Wic then
F.log(1,ffe[2363],ffe[3958]..tostring(Xic))
end
if not Oic then
local Yic=P.simTeam.dg
local Zic=tostring(Sic.r._r)
P.dg.swapFail=type(P.dg.swapFail)==ffe[1977]and P.dg.swapFail or{}
local _ic=tonumber(P.dg.swapFail[Zic])or 0
local ajc=jb.forced(Sic)
local bjc=(ajc and ajc.uuids)or((Yic and Yic.better and Yic.seed==Zic and _ic<2)and Yic.uuids)or P.savedTeam
local cjc=ib.team()
local djc= #cjc==6 and(not bjc or ib.same(cjc,bjc))
if not djc then
P.dg.swapFail[Zic]=_ic+1
local ejc={}
for fjc,gjc in ipairs(V.equipped())do
table.insert(ejc,V.name(gjc.id))
end
if _ic+1>=2 and Yic and Yic.better and Yic.seed==Zic then
Yic.better=false
F.log(1,ffe[2990],string.format(ffe[3959],Sic.d))
pcall(ab.restoreTeam)
end
F.log(1,ffe[3870],string.format(ffe[3960],Sic.d,#cjc,table.concat(ejc,ffe[2089])))
F.status(ffe[3008],ffe[3961]..Sic.d)
W.rec(ffe[2689]).restUntil=os.time()+45
P.pending=nil
F.saveSoon()
return false
end
P.dg.swapFail[Zic]=nil
local hjc,ijc=pcall(kb.relicsApply)
if not hjc then
