local kjc=(P.dg.lost[tostring(Sic.r._r)]or{})[W.teamSig()]or 0
local ljc= #V.equipped()<6
if(not jjc or kjc>=2 or ljc)and not(jb.playLast()and not ljc)then
local mjc=ljc and string.format(ffe[3962],#V.equipped())or kjc>=2 and string.format(ffe[3963],kjc)or ffe[3964]
jb.note(string.format(ffe[3965],Sic.d,mjc))
W.rec(ffe[2689]).restUntil=os.time()+3600
P.pending=nil
F.saveSoon()
return false
end
end
P.dg.room={seed=Sic.r._r,d=Sic.d}
P.pending={key=ffe[2689],kind=ffe[1997],level=ffe[1997],diff=ffe[2421],label=ffe[3966]..Sic.d,at=os.time(),value=Nic,depth=Sic.d}
if P.nextMode==ffe[2689]then
P.nextMode=nil
end
local njc,ojc,pjc=jb.res(Mic)
local qjc=string.format(ffe[3967],math.floor(Sic.p*100+0.5),Sic.sim and(ffe[3968]..tostring(Sic.sim.margin)..ffe[2632])or ffe[898],Sic.nextRoom and jb.roomName(Sic.nextRoom)or ffe[3969],jb.lives(Mic),njc,ojc,pjc)
F.log(1,ffe[2592],string.format(ffe[3970],Sic.d,jb.ROOMS,Oic and ffe[3971]or ffe[898],jb.roomName(Sic),qjc))
local rjc={}
for sjc,tjc in ipairs(jb._pick and jb._pick.rooms or{})do
