table.insert(rjc,string.format(ffe[3972],jb.roomName(tjc),math.floor((tjc.p or 0)*100+0.5),tjc.blocked and(ffe[3973]..tjc.blocked..ffe[2632])or ffe[898]))
end
end
if#rjc>0 then
