end
F.saveNow()
F.status(ffe[3008],ffe[3975]..Sic.d)
local ujc=type(Mic.selected_next)==ffe[1977]and Mic.selected_next.choice_str and tostring(Mic.selected_next.choice_str)or nil
local vjc={tostring(Sic.key)}
if ujc and ujc~=tostring(Sic.key)and not Oic then
table.insert(vjc,ujc)
end
for wjc,xjc in ipairs(vjc)do
if wjc==2 then
local yjc
for zjc,Ajc in ipairs(jb.rooms(Mic))do
if tostring(Ajc.key)==xjc then
yjc=Ajc
end
end
F.log(1,ffe[3870],string.format(ffe[3976],xjc,yjc and jb.roomName(yjc)or ffe[2212]))
end
local Bjc,Cjc=F.request(ffe[3977],ffe[3978],xjc)
local Djc=U.now()
