function jb.chain()
task.wait(4)
local Ejc=jb.data()
if not(Ejc and Ejc._started)then
return false
end
return jb.enter(Ejc,O.dungeonValue,true)
end
jb.WAY_WORDS={fast=ffe[3981],balanced=ffe[3764],box=ffe[3659]}
function jb.ways(Fjc)
local function Gjc(Hjc,Ijc,Jjc)
