function bb.buildPath()
bb.samples={}
local Nkc=N.PATH and N.PATH.PATH_CACHE and N.PATH.PATH_CACHE[workspace._BASES.pve]
if not Nkc then
return
end
for Okc,Pkc in pairs(Nkc)do
if not(N.PATH.HIDDEN_MOCK_LANES and N.PATH.HIDDEN_MOCK_LANES[Okc.Name])then
local Qkc={}
for Rkc,Skc in ipairs(Pkc.points or{})do
table.insert(Qkc,Skc.part.Position)
end
local Tkc=0
for Ukc=2,#Qkc do
Tkc=Tkc+(Qkc[Ukc]-Qkc[Ukc-1]).Magnitude
end
local Vkc=0
for Wkc=2,#Qkc do
local Xkc,Ykc=Qkc[Wkc-1],Qkc[Wkc]
local Zkc=(Ykc-Xkc).Magnitude
local _kc=math.max(1,math.floor(Zkc/2))
for alc=0,_kc-1 do
local blc=Xkc:Lerp(Ykc,alc/_kc)
table.insert(bb.samples,{pos=blc,prog=(Vkc+Zkc*alc/_kc)/math.max(1,Tkc),lane=Okc.Name})
end
Vkc=Vkc+Zkc
end
if Qkc[#Qkc]then
table.insert(bb.samples,{pos=Qkc[#Qkc],prog=1,lane=Okc.Name})
end
end
end
pcall(bb.readHidden,Nkc)
bb.laneCut,bb.laneWant,bb.laneFirst=nil,nil,nil
local clc=tonumber(bb.ld and bb.ld._portal_lanes)
local dlc=gb.laneList(bb.samples)
if clc and clc>=1 and dlc and#dlc>clc then
bb.laneWant=clc
end
bb.laneTotal=dlc and#dlc or 1
bb.countLanes()
