function bb.readHidden(elc)
local flc=N.PATH and N.PATH.HIDDEN_MOCK_LANES
if type(flc)~=ffe[1977]or not next(flc)or not(bb.ld and bb.ld.map)or not bb.samples[1]then
return
end
local glc
for hlc,ilc in pairs(elc)do
if flc[hlc.Name]and type(ilc.points)==ffe[1977]and#ilc.points>=2 then
local jlc={}
for klc,llc in ipairs(ilc.points)do
jlc[klc]=U.flat(llc.part.Position)
end
local mlc={}
for nlc,olc in ipairs(bb.samples)do
local plc=tostring(olc.lane)
mlc[plc]=mlc[plc]or{}
table.insert(mlc[plc],olc)
end
local qlc,rlc
for slc,tlc in pairs(mlc)do
local ulc=0
for vlc=1,#jlc,math.max(1,math.floor(#jlc/20))do
local wlc=math.huge
for xlc,ylc in ipairs(tlc)do
local zlc=(U.flat(ylc.pos)-jlc[vlc]).Magnitude
if zlc<wlc then
wlc=zlc
end
end
ulc=ulc+wlc
end
if not rlc or ulc<rlc then
qlc,rlc=slc,ulc
end
end
local Alc,Blc,Clc,Dlc,Elc,Flc={},nil,nil,nil,0,0
for Glc,Hlc in ipairs(jlc)do
local Ilc,Jlc=nil,math.huge
for Klc,Llc in ipairs(mlc[qlc])do
local Mlc=(U.flat(Llc.pos)-Hlc).Magnitude
if Mlc<Jlc then
Jlc,Ilc=Mlc,Llc.prog
end
end
Flc=math.max(Flc,Jlc)
if Clc then
local Nlc=Ilc-Clc
local Olc=(Nlc>0.002 and 1)or(Nlc< -0.002 and-1)or Dlc
if Dlc and Olc and Olc~=Dlc then
table.insert(Alc,math.floor(Clc*1000+0.5)/1000)
end
Dlc,Elc=Olc or Dlc,Elc+math.abs(Nlc)
else
Blc=Ilc
end
Clc=Ilc
if Glc%50==0 then
task.wait()
end
end
if Clc and Flc<=8 then
table.insert(Alc,math.floor(Clc*1000+0.5)/1000)
glc=glc or{}
glc[hlc.Name]={from=math.floor((Blc or 0)*1000+0.5)/1000,len=math.floor(Elc*1000+0.5)/1000,turns=Alc,road=qlc}
end
end
end
if not glc then
return
end
local Plc=bb.ld.map
P.maps[Plc]=P.maps[Plc]or{}
local Qlc=P.maps[Plc].hidden
P.maps[Plc].hidden=glc
if type(Qlc)~=ffe[1977]then
for Rlc,Slc in pairs(glc)do
F.log(1,ffe[2639],string.format(ffe[3998],Rlc,Slc.len,tostring(Slc.road),math.floor((#Slc.turns-1)/2)))
end
F.saveSoon()
end
end
