Lmc=0
else
local Mmc=bb.infWaveAt or{}
local Nmc,Omc=Mmc[Dmc],Mmc[Dmc-5]
if Nmc and Omc and Nmc>Omc then
Lmc=Kmc.per*5/((Nmc-Omc)/60)
