if bb.blockedSpot(dpc)then
return nil
end
local epc=(tonumber(apc.override_hitbox_radius)or 1.5)+0.25
bb.probe.Size=Vector3 .new(epc*2,2.5,epc*2)
bb.probe.CFrame=CFrame.new(dpc+Vector3 .new(0,1.35,0))
if#workspace:GetPartsInPart(bb.probe,bb.overlap)>0 then
return nil
end
local fpc=U.flat(dpc)
for gpc,hpc in ipairs(bb.mine or{})do
local ipc=hpc:FindFirstChild(ffe[4034])
local jpc=ipc and ipc.Position or hpc:GetPivot().Position
local kpc=ipc and math.max(ipc.Size.X,ipc.Size.Z)/2 or 1.5
if(fpc-U.flat(jpc)).Magnitude<epc+kpc then
return nil
end
end
if not bpc then
for lpc,mpc in ipairs(bb.blockers())do
if(fpc-mpc.p).Magnitude<epc+mpc.r then
return nil
end
end
end
return dpc
end
function bb.buildCandidates()
