if not V.isFarm(Epc.id.Value)and Epc:FindFirstChild(ffe[2229])then
table.insert(Bpc,{p=U.flat(Dpc:GetPivot().Position),r=Epc.range.Value*(V.SUMMONER[Epc.id.Value]and V.SUMMONER[Epc.id.Value].reach or 1),air=bb.canAir(Dpc)})
