for Hpc,Ipc in ipairs(bb.samples)do
if Ipc.prog>Gpc then
local Jpc=U.flat(Ipc.pos)
for Kpc,Lpc in ipairs(Bpc)do
if(Jpc-Lpc.p).Magnitude<=Lpc.r then
if Ipc.prog>Fpc then
Fpc=Ipc.prog
end
if Lpc.air then
Gpc=Ipc.prog
break
end
end
end
end
end
