local Opc={}
for Ppc,Qpc in ipairs(bb.samples)do
local Rpc=U.flat(Qpc.pos)
for Spc,Tpc in ipairs(Bpc)do
if(Rpc-Tpc.p).Magnitude<=Tpc.r then
local Upc=tostring(Qpc.lane)
Opc[Upc]=(Opc[Upc]or 0)+1
if Qpc.prog>(Mpc[Upc]or 0)then
Mpc[Upc]=Qpc.prog
end
break
end
end
end
local Vpc,Wpc={},0
for Xpc,Ypc in pairs(Npc.by)do
Vpc[Xpc]=(Opc[Xpc]or 0)/math.max(1,Ypc)
Wpc=math.max(Wpc,Vpc[Xpc])
end
bb.laneW={}
for Zpc,_pc in pairs(Npc.by)do
bb.laneW[Zpc]=(Npc.avg/math.max(1,_pc))*(1+1.5*(Wpc>0 and(1-Vpc[Zpc]/Wpc)or 0))
