local aqc,bqc,cqc
if#Bpc>0 then
for dqc,eqc in ipairs(Apc)do
local fqc=(bb.laneW and eqc.lane)and(Mpc[tostring(eqc.lane)]or 0)or Fpc
if eqc.hp>0 and eqc.prog>fqc+0.02 and eqc.prog>(aqc or 0)then
aqc,cqc=eqc.prog,bb.laneW and eqc.lane or nil
end
if eqc.hp>0 and eqc.fly and eqc.prog>Gpc+0.02 then
bqc=true
end
end
end
local gqc= #Bpc>0 and(bb.pressure or 0)>=Fpc-0.08
return{covEnd=Fpc,airEnd=Gpc,leak=aqc,leakLane=cqc,covL=Mpc,airLeak=bqc,push=gqc,units= #Bpc}
end
