bb.LAYOUT_KEEP,bb.LAYOUT_CONTROL,bb.HIVE_ASIDE,bb.HIVE_LEAD,bb.HIVE_LEAD_MIN=8,2,3600,0.015,300
function bb.layoutRecFor(aIc,bIc)
local cIc=bb.bookKey(aIc)
P.layoutRec=type(P.layoutRec)==ffe[1977]and P.layoutRec or{}
local dIc=P.layoutRec[cIc]
if type(dIc)~=ffe[1977]then
if not bIc then
return nil
end
dIc={at=os.time()}
P.layoutRec[cIc]=dIc
if U.count(P.layoutRec)>80 then
local eIc,fIc
for gIc,hIc in pairs(P.layoutRec)do
local iIc=type(hIc)==ffe[1977]and tonumber(hIc.at)or 0
if not fIc or iIc<fIc then
eIc,fIc=gIc,iIc
end
end
P.layoutRec[eIc]=nil
end
end
return dIc
end
function bb.layoutAdd(jIc,kIc,lIc,mIc,nIc)
jIc.runs,jIc.wins=(tonumber(jIc.runs)or 0)+1,(tonumber(jIc.wins)or 0)+(kIc and 1 or 0)
jIc.sec,jIc.wave=type(jIc.sec)==ffe[1977]and jIc.sec or{},type(jIc.wave)==ffe[1977]and jIc.wave or{}
if kIc and tonumber(lIc)then
table.insert(jIc.sec,math.floor(lIc+0.5))
end
table.insert(jIc.wave,tonumber(mIc)or 0)
if tonumber(nIc)then
jIc.kills=type(jIc.kills)==ffe[1977]and jIc.kills or{}
table.insert(jIc.kills,math.floor(tonumber(nIc)))
while#jIc.kills>bb.LAYOUT_KEEP do
table.remove(jIc.kills,1)
end
end
while#jIc.sec>bb.LAYOUT_KEEP do
table.remove(jIc.sec,1)
end
while#jIc.wave>bb.LAYOUT_KEEP do
table.remove(jIc.wave,1)
end
end
function bb.layoutJudge(oIc,pIc,qIc,rIc)
local sIc,tIc=tonumber(oIc and oIc.runs)or 0,tonumber(pIc and pIc.runs)or 0
if sIc<1 or tIc<bb.LAYOUT_CONTROL then
return nil
end
if rIc and type(oIc.kills)==ffe[1977]and type(pIc.kills)==ffe[1977]and#oIc.kills>=1 and#pIc.kills>=bb.LAYOUT_CONTROL then
local uIc,vIc=bb.labMedian(oIc.kills),bb.labMedian(pIc.kills)
if uIc and vIc and uIc<vIc*0.97 and(#oIc.kills>=2 or uIc<vIc*0.85)then
return string.format(ffe[4180],uIc,vIc)
end
return nil
end
local wIc,xIc=(tonumber(oIc.wins)or 0)/sIc,(tonumber(pIc.wins)or 0)/tIc
if not qIc and xIc>=0.5 then
if wIc+0.25<xIc and(sIc>=2 or(wIc==0 and xIc>=0.9 and tIc>=3))then
return string.format(ffe[4181],tonumber(oIc.wins)or 0,sIc,sIc==1 and ffe[898]or ffe[1825],tonumber(pIc.wins)or 0,tIc)
end
local yIc,zIc=bb.labMedian(oIc.sec),bb.labMedian(pIc.sec)
if yIc and zIc and yIc>zIc*1.10 and(#oIc.sec>=2 or yIc>zIc*1.25)then
return string.format(ffe[4182],math.floor(yIc/60),yIc%60,math.floor(zIc/60),zIc%60)
end
return nil
end
local AIc,BIc=bb.labMedian(oIc.wave),bb.labMedian(pIc.wave)
if AIc and BIc and AIc<BIc-math.max(1,BIc*0.03)and(sIc>=2 or AIc<BIc*0.85)then
return string.format(ffe[4183],AIc,BIc)
end
return nil
end
function bb.layoutResult(CIc,DIc)
local EIc=bb.info
local FIc=bb.layoutSrc
if not(EIc and FIc)or bb.labTest or bb.withOthers or bb.fastAlways then
return
end
if bb.infinite and not EIc.timeLimit then
return
end
local GIc=bb.wave()
local HIc=bb.layoutRecFor(EIc,true)
HIc.at=os.time()
local IIc=EIc.timeLimit~=nil
local JIc=EIc.killScore and true or nil
local KIc=JIc and(bb.killsEnd or bb.realKills())or nil
if FIc==ffe[4153]then
local LIc=bb.bookFor(EIc)
if not LIc then
return
end
LIc.real=type(LIc.real)==ffe[1977]and LIc.real or{}
bb.layoutAdd(LIc.real,CIc,DIc,GIc,KIc)
local MIc=LIc.aside==nil and bb.layoutJudge(LIc.real,HIc.own,IIc,JIc)or nil
if MIc then
LIc.aside={at=os.time(),why=MIc}
F.log(1,ffe[4099],string.format(ffe[4184],MIc))
end
else
HIc[FIc]=type(HIc[FIc])==ffe[1977]and HIc[FIc]or{}
local NIc=HIc[FIc]
bb.layoutAdd(NIc,CIc,DIc,GIc,KIc)
if FIc==ffe[3533]and NIc.aside==nil then
local OIc=bb.layoutJudge(NIc,HIc.own,IIc,JIc)
if OIc then
NIc.aside,NIc.why=os.time(),OIc
F.log(1,ffe[4099],string.format(ffe[4185],OIc))
end
end
end
F.saveSoon()
end
bb.CONTROL_WORDS={ffe[4186],ffe[4187],ffe[4188],ffe[4189]}
function bb.controlSpot(PIc,QIc)
if not bb.killZone()then
return nil
end
local RIc=gb.holds
if not RIc(PIc.id)or V.toggleOf(PIc.id)then
return nil
end
local SIc,TIc,UIc,VIc=1,0,0,{}
local WIc=bb.hurtSamples()
for XIc,YIc in ipairs(bb.mine or{})do
local ZIc=YIc._stats
local _Ic=ZIc.id.Value
if ZIc:FindFirstChild(ffe[2229])and not V.isFarm(_Ic)and not V.allyBuff(_Ic)then
local aJc,bJc=U.flat(YIc:GetPivot().Position),ZIc.range.Value
if RIc(_Ic)and not V.toggleOf(_Ic)then
UIc=UIc+1
table.insert(VIc,{p=aJc,r=bJc})
else
for cJc,dJc in ipairs(WIc)do
if(U.flat(dJc.pos)-aJc).Magnitude<=bJc then
SIc,TIc=math.min(SIc,dJc.prog),math.max(TIc,dJc.prog)
end
end
end
end
end
if TIc<=SIc then
SIc,TIc=0.75,0.98
end
local eJc=(QIc or UIc)+1
local fJc=({SIc,TIc,(SIc+TIc)/2,SIc-(TIc-SIc)/2})[eJc]
if not fJc then
return nil
end
local gJc=V.range(PIc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local hJc={}
for iJc,jJc in ipairs(bb.cands)do
local kJc,lJc,mJc=U.flat(jJc),0,0
for nJc,oJc in ipairs(WIc)do
if(U.flat(oJc.pos)-kJc).Magnitude<=gJc then
mJc=mJc+1
if math.abs(oJc.prog-fJc)<=0.05 then
lJc=lJc+1
local pJc=U.flat(oJc.pos)
for qJc,rJc in ipairs(VIc)do
if(pJc-rJc.p).Magnitude<=rJc.r then
lJc=lJc-0.5
break
end
end
end
end
end
if lJc>0 then
table.insert(hJc,{pos=jJc,sc=lJc,cov=mJc})
end
if iJc%60==0 then
task.wait()
end
end
table.sort(hJc,function(sJc,tJc)
return sJc.sc>tJc.sc
end)
for uJc,vJc in ipairs(hJc)do
local wJc=bb.valid(vJc.pos,PIc.data)
if wJc then
F.log(1,ffe[4038],string.format(ffe[4190],V.name(PIc.id),bb.CONTROL_WORDS[eJc],math.floor(fJc*100+0.5)))
return wJc,vJc.cov,fJc
end
if uJc%20==0 then
task.wait()
end
end
return nil
end
function bb.holdSpot(xJc)
local yJc,zJc=gb.holds(xJc.id)
if not yJc then
return nil
end
if V.killFed(xJc.id)then
return nil
end
local AJc,BJc={},0
for CJc,DJc in ipairs(bb.mine or{})do
local EJc=DJc._stats
local FJc=EJc.id.Value
if EJc:FindFirstChild(ffe[2229])and not V.isFarm(FJc)and not V.allyBuff(FJc)and FJc~=xJc.id then
local GJc,HJc=pcall(bb.liveDps,DJc,FJc)
HJc=GJc and tonumber(HJc)or 0
if HJc>0 then
table.insert(AJc,{p=U.flat(DJc:GetPivot().Position),r=EJc.range.Value,d=HJc})
BJc=BJc+HJc
end
end
end
if#AJc==0 or BJc<=0 then
return nil
end
local IJc=bb.hurtSamples()
local JJc={}
for KJc,LJc in ipairs(IJc)do
local MJc,NJc=U.flat(LJc.pos),0
for OJc,PJc in ipairs(AJc)do
if(MJc-PJc.p).Magnitude<=PJc.r then
NJc=NJc+PJc.d
end
end
JJc[KJc]=NJc/BJc
end
local QJc=V.range(xJc.u,math.min(tonumber(zJc)or 0,3,V.rows(xJc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1)
local RJc,SJc,TJc
for UJc,VJc in ipairs(bb.cands)do
local WJc,XJc,YJc=U.flat(VJc),0,0
for ZJc,_Jc in ipairs(IJc)do
if(U.flat(_Jc.pos)-WJc).Magnitude<=QJc then
XJc=XJc+JJc[ZJc]
YJc=YJc+1
end
end
if XJc>0 and(not SJc or XJc>SJc)then
local aKc=bb.valid(VJc,xJc.data)
if aKc then
RJc,SJc,TJc=aKc,XJc,YJc
end
end
if UJc%40==0 then
task.wait()
end
end
if not RJc then
return nil
end
bb.holdSaid=bb.holdSaid or{}
if not bb.holdSaid[xJc.id]then
bb.holdSaid[xJc.id]=true
F.log(1,ffe[4038],string.format(ffe[4191],V.name(xJc.id)))
end
return RJc,TJc or 0
end
function bb.bestSpot(bKc,cKc,dKc)
if bb.hybridHill and not bKc._hillTry and type(bKc.data)==ffe[1977]and bKc.data.hybrid_placement and not bKc.data.hill_unit then
local eKc=setmetatable({data=bb.hillData(bKc.data),_hillTry=true},{__index=bKc})
local fKc,gKc,hKc=pcall(bb.bestSpot,eKc,cKc,dKc)
if fKc and gKc then
return gKc,hKc
end
end
if bb.focus and not cKc and not dKc and not V.allyBuff(bKc.id)then
local iKc,jKc=bb.focusSpot(bKc)
if iKc then
return iKc,jKc
end
end
if O.fishiFollow and not cKc and not dKc then
local kKc,lKc,mKc,nKc,oKc=pcall(bb.drownBoss)
if kKc and lKc and not mKc and oKc and oKc[bKc.id]then
local pKc,qKc,rKc=pcall(bb.drownSpot,bKc,lKc)
if pKc and qKc then
return qKc,rKc
end
end
end
if not cKc and not dKc and not(bb.depth and bb.depth.leak)then
local sKc,tKc,uKc=pcall(bb.controlSpot,bKc)
if sKc and tKc then
return tKc,uKc
end
local vKc,wKc,xKc=pcall(bb.holdSpot,bKc)
if vKc and wKc then
return wKc,xKc
end
end
local yKc=bb.depth and bb.depth.leak
if bb.layout and bb.layout[bKc.id]and not cKc and not dKc then
local zKc=false
for AKc,BKc in ipairs(bb.mine or{})do
local CKc=BKc._stats:FindFirstChild(ffe[2353])
if CKc and CKc.Value==bKc.uuid then
zKc=true
break
end
end
if not zKc then
for DKc,EKc in ipairs(bb.layout[bKc.id])do
local FKc=bb.valid(EKc,bKc.data)
if FKc and bb.sandLine()>0 and bb.cover(FKc,V.range(bKc.u,V.rows(bKc.id).max)*((bb.info and tonumber(bb.info.rangeScale))or 1))<=0 then
FKc=nil
end
if FKc and yKc then
local GKc,HKc,IKc=false,U.flat(FKc),V.range(bKc.u,0)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local JKc=bb.depth and bb.depth.leakLane and tostring(bb.depth.leakLane)or nil
for KKc,LKc in ipairs(bb.hurtSamples())do
if LKc.prog>=yKc+0.02 and(not JKc or tostring(LKc.lane)==JKc)and(U.flat(LKc.pos)-HKc).Magnitude<=IKc then
GKc=true
break
end
end
if not GKc then
FKc=nil
end
end
if FKc then
bb.layoutUsed=bb.layoutUsed or{}
bb.layoutUsed[bKc.id]=FKc
return FKc,bb.cover(FKc,V.range(bKc.u,math.min(3,V.rows(bKc.id).max))*((bb.info and tonumber(bb.info.rangeScale))or 1))
end
end
end
end
local MKc=bKc.data
local NKc=bb.depth
local OKc,PKc=bb.hurtSamples(),bb.sandLine()
local QKc
if dKc then
QKc=1
for RKc,SKc in ipairs(bb.mine or{})do
local TKc=SKc._stats
if not V.isFarm(TKc.id.Value)and not(TKc:FindFirstChild(ffe[2353])and TKc.uuid.Value==bKc.uuid)then
local UKc,VKc=U.flat(SKc:GetPivot().Position),TKc.range.Value
for WKc,XKc in ipairs(OKc)do
if XKc.prog<QKc and(U.flat(XKc.pos)-UKc).Magnitude<=VKc then
QKc=XKc.prog
end
end
end
end
if V.ENTRY[bKc.id]or(bb.studyEntry and bKc.id==bb.trialId)then
QKc=math.min(QKc,PKc+0.1)
end
end
local YKc=(bb.info and tonumber(bb.info.rangeScale))or 1
local ZKc=V.range(bKc.u,(NKc and NKc.leak)and 0 or math.min(3,V.rows(bKc.id).max))*YKc
local _Kc=(bb.kind==ffe[1997]or bb.style==ffe[3634]or bb.style==ffe[3635])and not cKc and not(NKc and NKc.leak)and not V.isFarm(bKc.id)and V.range(bKc.u,V.rows(bKc.id).max)*YKc or nil
local aLc=V.allyBuff(bKc.id)
if bb.killZone()and not cKc and not dKc and not aLc and not(NKc and NKc.leak)and not V.isFarm(bKc.id)then
local bLc=_Kc or ZKc
local cLc={}
for dLc,eLc in ipairs(bb.mine or{})do
local fLc=eLc._stats
local gLc=fLc.id.Value
if not V.isFarm(gLc)and not V.allyBuff(gLc)and fLc:FindFirstChild(ffe[2229])then
table.insert(cLc,{p=U.flat(eLc:GetPivot().Position),r=fLc.range.Value})
