end
local bSc,cSc,dSc=bb.buffShort(aSc)
local eSc=V.stackCap(aSc.attack)
local fSc,gSc=pcall(V.range,_Rc.u,0)
gSc=(fSc and tonumber(gSc)or 15)*((bb.info and tonumber(bb.info.rangeScale))or 1)
local hSc=eSc and O.community and tonumber(aSc.time)and tonumber(dSc)
local function iSc(jSc,kSc)
local lSc=math.floor(jSc*aSc.time/math.max(1,dSc)+0.001)
return math.min(eSc,(1+kSc)^lSc-1)
end
local mSc=0
for nSc,oSc in ipairs(bSc)do
local pSc=0
for qSc,rSc in ipairs(bSc)do
if(rSc.pos-oSc.pos).Magnitude<=gSc then
local sSc=aSc.types[rSc.base]
local tSc=sSc*aSc.uptime
if hSc then
local uSc,vSc=iSc(rSc.n,sSc),rSc.n+1
while vSc<rSc.n+6 and iSc(vSc,sSc)<=uSc+0.001 do
vSc=vSc+1
end
tSc=math.max(0,(iSc(vSc,sSc)-uSc)/(vSc-rSc.n))
elseif eSc then
tSc=math.max(0,math.min(eSc,(rSc.n+1)*sSc*aSc.uptime)-math.min(eSc,rSc.n*sSc*aSc.uptime))
end
pSc=pSc+rSc.dps*tSc
end
end
mSc=math.max(mSc,pSc)
end
return mSc*(hSc and 1 or 0.7)
end
