function nb.K.key(CNd,DNd)
local ENd,FNd,GNd=nb.K,nb.Win,Enum.KeyCode
if ENd.cur and not(ENd.cur.obj and ENd.cur.obj.Parent and ENd.shown(ENd.cur.obj))then
ENd.setFocus(nil)
end
if ENd.cur and ENd.cur.listKey and ENd.cur.listKey(CNd)then
return true
end
if CNd==GNd.PageUp or CNd==GNd.PageDown then
local HNd={}
for INd,JNd in pairs(FNd._tabs)do
table.insert(HNd,{name=INd,y=JNd.btn.AbsolutePosition.Y,on=JNd.page.Visible})
end
table.sort(HNd,function(KNd,LNd)
return KNd.y<LNd.y
end)
local MNd=1
for NNd,ONd in ipairs(HNd)do
if ONd.on then
MNd=NNd
end
end
MNd=(MNd-1+(CNd==GNd.PageDown and 1 or-1))% #HNd+1
ENd.setFocus(nil)
FNd:SelectTab(HNd[MNd].name)
return true
end
if CNd==GNd.Tab or CNd==GNd.Down or CNd==GNd.Up then
local PNd=ENd.order()
if#PNd==0 then
return true
end
local QNd=CNd==GNd.Up or(CNd==GNd.Tab and DNd)
local RNd=table.find(PNd,ENd.cur)
if not RNd then
RNd=QNd and#PNd or 1
else
RNd=(RNd-1+(QNd and-1 or 1))% #PNd+1
end
ENd.setFocus(PNd[RNd])
return true
end
if not ENd.cur then
return false
end
if CNd==GNd.Return or CNd==GNd.KeypadEnter or CNd==GNd.Space then
if ENd.cur.activate then
ENd.cur.activate()
end
return true
end
if CNd==GNd.Left or CNd==GNd.Right then
if ENd.cur.adjust then
ENd.cur.adjust(CNd==GNd.Right and 1 or-1)
end
return true
end
if CNd==GNd.Escape then
ENd.setFocus(nil)
return true
end
return false
end
